import{_ as e,c as a,o as r,b0 as l}from"./chunks/framework.Dmsv_Tiv.js";const m=JSON.parse('{"title":"LV005-概述","description":null,"frontmatter":{"title":"LV005-概述","date":"2025-12-09T16:40:30.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/vcodec/container/126b1a20e4fe19a7ee839a57","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2025-12-09T16:40:30.410Z","fulluuid":"7ee839a57d944a6db1d356e4712bd71f","useduuid":"7ee839a57"}},"headers":[],"relativePath":"sdoc/vcodec/container/126b1a20e4fe19a7ee839a57.md","filePath":"sdoc/20-视频编解码/15-封装/LV005-概述.md","lastUpdated":1767537778000}'),d={name:"sdoc/vcodec/container/126b1a20e4fe19a7ee839a57.md"};function n(o,t,i,h,p,s){return r(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="lv005-概述" tabindex="-1">LV005-概述 <a class="header-anchor" href="#lv005-概述" aria-label="Permalink to &quot;LV005-概述&quot;">​</a></h1><h2 id="一、视频封装格式简介" tabindex="-1">一、视频封装格式简介 <a class="header-anchor" href="#一、视频封装格式简介" aria-label="Permalink to &quot;一、视频封装格式简介&quot;">​</a></h2><h3 id="_1-文件格式" tabindex="-1">1. 文件格式 <a class="header-anchor" href="#_1-文件格式" aria-label="Permalink to &quot;1. 文件格式&quot;">​</a></h3><p>维基百科是这样说的：A file format is a particular way that information is encoded for storage in a computer file.</p><p>可以再看一下百度百科：文件格式是指电脑为了存储信息而使用的对信息特殊编码方式，用于识别内部存储的资料。</p><h3 id="_2-什么是视频的封装格式" tabindex="-1">2. 什么是视频的封装格式？ <a class="header-anchor" href="#_2-什么是视频的封装格式" aria-label="Permalink to &quot;2. 什么是视频的封装格式？&quot;">​</a></h3><p>看一眼百度喽：<a href="https://baike.baidu.com/item/%E5%B0%81%E8%A3%85%E6%A0%BC%E5%BC%8F/7015654" target="_blank" rel="noreferrer">封装格式_百度百科</a></p><p>封装格式又称多媒体容器，是将已编码的视频轨、音频轨及元数据按规范打包成单一文件的技术方案。主要分为面向存储（<a href="https://baike.baidu.com/item/AVI/213655?fromModule=lemma_inlink" target="_blank" rel="noreferrer">AVI</a>/MP4/MKV）和面向流媒体（FLV/<a href="https://baike.baidu.com/item/TS/2743866?fromModule=lemma_inlink" target="_blank" rel="noreferrer">TS</a>/MP4）两大类，常见格式包括 AVI、FLV、MKV、<a href="https://baike.baidu.com/item/MOV/213982?fromModule=lemma_inlink" target="_blank" rel="noreferrer">MOV</a>、MP4、TS、OGG 等。流媒体封装格式中 MP4 适配多终端但文件头过大，FLV 依赖 Flash 播放，TS 常用于 HLS 协议的分片传输。</p><p>所以呢，我们常说的视频封装格式，也就是容器，它是将已经编码压缩好的视频流、音频流以及字幕按照一定的方式放到一个文件中，方便播放软件播放。一般来说，视频文件的后缀名就是它的封装格式。</p><h3 id="_3-和编码格式有什么关系" tabindex="-1">3. 和编码格式有什么关系？ <a class="header-anchor" href="#_3-和编码格式有什么关系" aria-label="Permalink to &quot;3. 和编码格式有什么关系？&quot;">​</a></h3><p>前面我们已经学习过视频编码的原理，那我们可以知道，视频编码就是为了压缩视频数据而做的一种压缩算法，视频编码格式可以理解为不同压缩算法和方法的一种名称。也就是说假如现在有某个视频编码格式的文件，这个文件中是纯视频流数据。</p><p>业内有个很形象的比喻，可以很快弄清楚封装格式和编码的关系：编码格式和封装格式的关系好比 <strong>酒与酒瓶</strong> 的关系，编码格式就像酒瓶里的酒，是视频的核心内容，封装格式就像酒瓶，它只是负责把内部的视频轨、音频轨、字幕轨集成在一起。简单说，<strong>视频编码格式是视频的内核，封装格式是视频的外壳，</strong> 因此编码格式与封装格式对文件大小的影响也截然不同。</p><p>它们的关系可以简单理解为，<strong>封装格式包含了编码格式</strong>。后面学习具体的封装的时候就会有更深入的理解了。</p><h3 id="_4-为什么要有封装格式" tabindex="-1">4. 为什么要有封装格式 <a class="header-anchor" href="#_4-为什么要有封装格式" aria-label="Permalink to &quot;4. 为什么要有封装格式&quot;">​</a></h3><p>对于任何一部视频来说，仅有图像没有声音是不完整的。因此，在视频编码后，大家需要将音频编码与视频编码一起进行封装，以便于存储、传输和播放。</p><p>封装格式的主要作用是为多媒体编码提供一个“外壳”，将所有的视频、音频或字幕都包装到一个文件容器内。封装后，可以增加视音频的编码类型、时标、包大小、帧率以及各种私有信息。这样，观众就可以方便地播放、编辑和管理这些多媒体文件。</p><p>而不同的封装格式提供了不同的功能和特性，以满足各种使用场景的需求。某些格式更适合流式传输，而另一些格式则更适合高质量存储和编辑。封装格式的选择影响到文件的大小、兼容性、画质、音频质量以及是否支持字幕、章节等附加信息。</p><h3 id="_5-文件封装的基本结构" tabindex="-1">5. 文件封装的基本结构 <a class="header-anchor" href="#_5-文件封装的基本结构" aria-label="Permalink to &quot;5. 文件封装的基本结构&quot;">​</a></h3><ul><li><p>文件头：绝大多数情况下, 文件头为必需的, 文件头类似于协议的握手, 或是多媒体数据的格式声明。主要声明的封装格式, 视频编码、音频编码、以及一些基本不变的参数、如宽高、帧率等。</p></li><li><p>文件数据：必需的, 根据不同的封装格式, 码流数据(压缩的/未压缩的)以一定的结构, 或连续或分散地存放在文件中。</p></li><li><p>索引表：可选的, 也是很有用的。最常见的用途是关键帧定位，也可以用于数据帧位置，这样的表相对来说会大一些。</p></li></ul><h2 id="二、mpeg" tabindex="-1">二、MPEG <a class="header-anchor" href="#二、mpeg" aria-label="Permalink to &quot;二、MPEG&quot;">​</a></h2><p>这一部分，我们来了解一下 MPEG。</p><h3 id="_1-mpeg-是什么" tabindex="-1">1. MPEG 是什么？ <a class="header-anchor" href="#_1-mpeg-是什么" aria-label="Permalink to &quot;1. MPEG 是什么？&quot;">​</a></h3><p>可以看这里：<a href="https://mpeg.chiariglione.org/who-we-are.html" target="_blank" rel="noreferrer">Who we are | MPEG</a></p><p>MPEG（Moving Picture Experts Group） ，运动图像专家组。它是 ISO/IEC 的一个工作组，负责制定运动图像、音频及其组合的压缩、解压缩、处理和编码表示的国际标准。</p><h3 id="_2-一些国际标准" tabindex="-1">2. 一些国际标准 <a class="header-anchor" href="#_2-一些国际标准" aria-label="Permalink to &quot;2. 一些国际标准&quot;">​</a></h3><p>MPEG 国际标准包括 MPEG-1、MPEG-2、MPEG-4、MPEG-7 和 MPEG-21 等格式，其中 MPEG-2 和 MPEG-4 是最常用的。它们主要用于家用 DVD 播放器录制时的文件格式。</p><table><thead><tr><th width="100px"> 名称 </th><th> 应用 </th><th> 特点 </th></tr></thead><tbody><tr><td> MPEG-1 </td><td> VCD（Video Compact Disc）、MP3 音频 </td><td> 定义了视频和音频的压缩标准，使得视频和音频可以在 CD 等存储介质上存储和播放。扩展名通常为“.mpg”或“.mpeg”。</td></tr><tr><td> MPEG-2 </td><td> DVD、数字电视广播、有线电视 </td><td> 扩展了 MPEG-1 的标准，支持更高的分辨率和更高质量的视频和音频。定义了 Program Stream (PS) 和 Transport Stream (TS) 两种容器格式。扩展名有“.mpg”、“.mpeg”、“.m2p”和“.ts”。</td></tr><tr><td> MPEG-4 </td><td> 互联网视频、移动设备、流媒体 </td><td> 专注于多媒体内容的高效压缩和传输，支持多种音频和视频编码格式，如 H.264/AVC。</td></tr><tr><td> MPEG-7 </td><td> 多媒体内容的描述和检索 </td><td> 不是一种编码标准，而是一种多媒体内容描述接口标准，用于描述多媒体内容以支持高效检索。</td></tr><tr><td> MPEG-21 </td><td> 数字版权管理、多媒体内容的交互和分发 </td><td> 定义了一个多媒体框架，旨在提供一个统一的框架来处理和管理多媒体内容。</td></tr></tbody></table><h2 id="三、iso-与-iec" tabindex="-1">三、ISO 与 IEC <a class="header-anchor" href="#三、iso-与-iec" aria-label="Permalink to &quot;三、ISO 与 IEC&quot;">​</a></h2><ul><li><p>ISO 全称是 the International Organization for Standardization，国际标准化组织。</p></li><li><p>IEC 全称是 the International Electrotechnical Commission，国际电工委员会。</p></li></ul><p>这是两个国际组织，流媒体是他们共同的领域，他们会在共同感兴趣的领域进行合作。所以两个组织有时候一起合作，制定一些标准。</p><h2 id="四、常见封装格式" tabindex="-1">四、常见封装格式 <a class="header-anchor" href="#四、常见封装格式" aria-label="Permalink to &quot;四、常见封装格式&quot;">​</a></h2><p>常见的封装格式有很多，这里我们只简单介绍一些后面常用的，例如 AVI、MP4、PS、TS 等</p><h3 id="_1-avi" tabindex="-1">1. AVI <a class="header-anchor" href="#_1-avi" aria-label="Permalink to &quot;1. AVI&quot;">​</a></h3><p>1992 年微软推出，是 Windows 平台最早的成熟视频容器。支持多编码(如 DivX、XviD)，兼容性极强，但无压缩优化，文件体积庞大。不支持字幕、章节等信息，也不支持流媒体传输。主要用于早期的视频存储和编辑。</p><h3 id="_2-mp4-和-fmp4" tabindex="-1">2. MP4 和 FMP4 <a class="header-anchor" href="#_2-mp4-和-fmp4" aria-label="Permalink to &quot;2. MP4 和 FMP4&quot;">​</a></h3><h4 id="_2-1-mp4" tabindex="-1">2.1 MP4 <a class="header-anchor" href="#_2-1-mp4" aria-label="Permalink to &quot;2.1 MP4&quot;">​</a></h4><p>2001 年 ISO 基于苹果 QuickTime 容器改良而来，核心目标是解决 “跨平台兼容” 难题。支持几乎所有主流编码(H.264、H.265、AV1 等)，通过 “盒子嵌套” 结构(如 moov 盒子存索引、mdat 盒子存数据)实现高效流媒体传输，如今占互联网视频 70% 以上份额。</p><p>它的优点包括高兼容性、较小的文件大小和支持多音轨、字幕和元数据。常用于互联网视频流、移动设备和存储高清视频。</p><h4 id="_2-2-fmp4" tabindex="-1">2.2 FMP4 <a class="header-anchor" href="#_2-2-fmp4" aria-label="Permalink to &quot;2.2 FMP4&quot;">​</a></h4><p>FMP4 格式（Fragmented MP4）是一种视频和音频流媒体格式，是 MPEG-4 Part 12 标准的一种扩展。与传统的 MP4 格式不同，FMP4 格式将媒体文件分成若干个片段（Fragment），每个片段都是一个完整的 MP4 文件，其中包含了媒体数据、元数据和索引信息。</p><p>FMP4 格式的应用范围广泛, 包括直播、点播、视频会议等。它具有低延迟、高清晰度、高效传输等特点, 能够为用户带来更加流畅和稳定的视听体验。</p><h3 id="_4-mkv" tabindex="-1">4. MKV <a class="header-anchor" href="#_4-mkv" aria-label="Permalink to &quot;4. MKV&quot;">​</a></h3><p>2002 年由俄罗斯程序员发起的开源项目，核心诉求是打破 MP4 的功能限制。被誉为 “万能容器”—— 支持 16 条以上音轨、ASS 特效字幕和 FLAC 无损音频，且无版权费用，成为高清收藏爱好者的首选(B 站高清资源大多采用 MKV 封装)。</p><h3 id="_5-flv-f4v" tabindex="-1">5. FLV/ F4V <a class="header-anchor" href="#_5-flv-f4v" aria-label="Permalink to &quot;5. FLV/ F4V&quot;">​</a></h3><p>2003 年 Adobe 为 Flash 插件开发，是早期网页视频的 “代名词”。FLV 仅支持旧版编码，F4V 是其升级版(支持 H.264)，均依赖 Flash 播放。曾是 YouTube 2005-2015 年的主力格式，但因安全漏洞多、耗电高，2020 年被 Adobe 正式放弃，被 HTML5+MP4 组合取代。</p><h3 id="_6-mpeg-2-中的两种流" tabindex="-1">6. MPEG-2 中的两种流 <a class="header-anchor" href="#_6-mpeg-2-中的两种流" aria-label="Permalink to &quot;6. MPEG-2 中的两种流&quot;">​</a></h3><p>MPEG-2 标准中，有两种不同的码流可以输出到信号，一种是节目码流（PS Program Stream），一种是传输流（TS Transport Stream），如下表所示，对比了 TS 和 PS 格式：</p><table tabindex="0"><thead><tr><th style="text-align:center;">属性</th><th style="text-align:left;">TS（Transport Stream）</th><th>PS（Program Stream）</th></tr></thead><tbody><tr><td style="text-align:center;">定义</td><td style="text-align:left;">用于实时传输音视频流的数字容器格式。</td><td>用于高质量音视频存储的数字容器格式。</td></tr><tr><td style="text-align:center;">标准</td><td style="text-align:left;">MPEG-2 Part 1</td><td>MPEG-2 Part 1</td></tr><tr><td style="text-align:center;">主要用途</td><td style="text-align:left;">实时传输、流媒体传输、多路节目传输。</td><td>音视频存储（如 DVD 和蓝光光盘）。</td></tr><tr><td style="text-align:center;">数据包结构</td><td style="text-align:left;">固定大小的 188 字节包。</td><td>可变大小的数据包，通常更大。</td></tr><tr><td style="text-align:center;">容错能力</td><td style="text-align:left;">强，适合高误码环境（如广播电视、IP 网络）。</td><td>弱，适用于可靠介质（如光盘存储）。</td></tr><tr><td style="text-align:center;">支持的流数量</td><td style="text-align:left;">支持多路音视频流和数据流，使用 PID 区分。</td><td>通常只支持单路或少量流。</td></tr><tr><td style="text-align:center;">额外信息</td><td style="text-align:left;">提供用于同步和误码检测的头部信息。</td><td>包含更多详细的节目信息，便于解码。</td></tr><tr><td style="text-align:center;">典型应用场景</td><td style="text-align:left;">数字电视广播（DVB）、IPTV、HLS、实时传输。</td><td>DVD、蓝光光盘、文件存储、视频编辑软件。</td></tr><tr><td style="text-align:center;">设计目标</td><td style="text-align:left;">传输效率与容错能力优先，适合动态网络环境。</td><td>存储效率与解码便捷优先，适合高质量数据存储。</td></tr><tr><td style="text-align:center;">转码/封装需求</td><td style="text-align:left;">传输过程中可能需要解封装为 PS，用于存储或后处理。</td><td>在分发或实时预览时可能封装为 TS，用于传输。</td></tr></tbody></table><p>值得注意的是 TS、PS 封装 H264/H265 的时候都会采用 Annex B 格式，</p><h3 id="_7-3gp" tabindex="-1">7. 3GP <a class="header-anchor" href="#_7-3gp" aria-label="Permalink to &quot;7. 3GP&quot;">​</a></h3><p>3GP（<a href="https://baike.baidu.com/item/3GPP/2373775?fromModule=lemma_inlink" target="_blank" rel="noreferrer">3GPP</a> 文件格式）是第三代合作伙伴项目计划（3GPP）于 1998 年为 3G 移动通信网络设计的多媒体容器格式，主要应用于 3G 手机，也兼容部分 2G 和 4G 设备。</p><p>该格式基于 MPEG-4Part 14 简化版本，采用 ISO 基本媒体文件格式结构，支持 H.263、MPEG-4 及 H.264 等视频编码标准，音频采用 AMR-NB/WB 或 AAC 编解码器。文件扩展名分为.3gp（GSM 设备）和.3g2（CDMA 设备）。</p><p>3GP 封装的数据传输时封装与 RTP 一样，存储时类似 AVI 文件, 有索引信息帮助定位帧, 索引信息可放文件头, 也可放文件尾。</p><blockquote><p>参考资料：</p><p><a href="https://www.cnblogs.com/wzzkaifa/p/19126222" target="_blank" rel="noreferrer">实用指南：流媒体基础解析：音视频封装格式与传输协议 - wzzkaifa - 博客园</a></p><p><a href="https://cloud.tencent.com/developer/article/2462525" target="_blank" rel="noreferrer">视频编码格式和封装格式有什么关系？相机常见的编码格式有哪些？-腾讯云开发者社区-腾讯云</a></p><p><a href="https://blog.csdn.net/weekend_y45/article/details/125235203" target="_blank" rel="noreferrer">什么是视频封装格式和编码格式-CSDN 博客</a></p><p><a href="https://mp.weixin.qq.com/s/kYf0_VC5mYgT2WFZfdL6mA" target="_blank" rel="noreferrer">什么是电影封装格式？10 种常见视频格式揭秘</a></p><p><a href="https://mp.weixin.qq.com/s/nMME4qYyUgNsmRmzAlHVew" target="_blank" rel="noreferrer">视频编码格式有哪些？视频封装格式有哪些？视频封装格式和编码格式的区别</a></p><p><a href="https://blog.csdn.net/qq_39431405/article/details/131920453" target="_blank" rel="noreferrer">音视频——封装格式原理_音视频封装-CSDN 博客</a></p><p><a href="http://www.max-shu.com/blog/wp-content/uploads/2018/03/MPEG%E5%9F%BA%E7%A1%80%E5%92%8C%E5%8D%8F%E8%AE%AE%E5%88%86%E6%9E%90%E6%8C%87%E5%8D%97.pdf" target="_blank" rel="noreferrer">MPEG 基础和协议分析指南</a></p><p><a href="https://www.cnblogs.com/BreakingY/p/18677351" target="_blank" rel="noreferrer">MPEG2: TS、PS - BreakingY - 博客园</a></p></blockquote>',54)])])}const P=e(d,[["render",n]]);export{m as __pageData,P as default};
